DROP FUNCTION IF EXISTS public.admin_delete_user(uuid, text);
CREATE FUNCTION public.admin_delete_user(_uid uuid,_reason text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE rid uuid; BEGIN IF _uid IS NULL OR _uid=auth.uid() OR length(trim(coalesce(_reason,'')))<3 OR length(_reason)>1000 THEN RAISE EXCEPTION 'Invalid deletion request'; END IF; IF EXISTS(SELECT 1 FROM admin_roles WHERE user_id=_uid) THEN RAISE EXCEPTION 'Remove admin roles before deleting'; END IF; IF NOT EXISTS(SELECT 1 FROM profiles WHERE id=_uid) THEN RAISE EXCEPTION 'User not found'; END IF; PERFORM public.admin_require_write('users_delete','user_delete_requested',_uid,jsonb_build_object('reason',_reason)); INSERT INTO public.admin_user_deletions(actor_id,target_user_id,reason) VALUES(auth.uid(),_uid,trim(_reason)) RETURNING id INTO rid; RETURN rid; END $$;
REVOKE ALL ON FUNCTION public.admin_delete_user(uuid,text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.admin_delete_user(uuid,text) TO authenticated, service_role;
COMMENT ON FUNCTION public.admin_delete_user(uuid,text) IS 'Queues audited MFA-authorized deletion. Complete via POST /api/public/admin-delete-user using the supported Auth admin API.';